import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

primes_q = [2, 3, 5, 7, 11, 13, 17]
results = []

for q in primes_q:
    N = q**2 - q + 1

    # Find integer cube root p
    # We use round(N**(1/3)) for approximation, then verify
    p_candidate = round(N**(1/3))

    if p_candidate**3 == N:
        p = p_candidate

        # Check conditions: p is prime and p != q
        is_p_prime = is_prime(p)
        is_p_neq_q = p != q

