import math

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n, sqrt_n

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

primes_to_check = [13, 19, 31, 37, 43, 61, 67, 73, 79, 97]
results = {}

for p in primes_to_check:
    N = 4 * (p**3) - 3
    is_square, D = is_perfect_square(N)

    result_entry = {"p": p, "is_square": is_square, "D": D, "q_candidate": None, "q_is_prime": False}

    if is_square:
        # q = (1 + D) / 2
        if (1 + D) % 2 == 0:
            q = (1 + D) // 2
            result_entry["q_candidate"] = q
            result_entry["q_is_prime"] = is_prime(q)
            # Final check: q is prime AND q != p
            result_entry["valid_solution"] = result_entry["q_is_prime"] and (q != p)
        else:
            # Should not happen since D^2 = 4p^3 - 3, D must be odd because 4p^3 is even and 3 is odd.
            result_entry["q_candidate"] = "Error: D is even"
            result_entry["valid_solution"] = False
    else:
        result_entry["valid_solution"] = False

    results[p] = result_entry

for p, res in results.items():
    print(f"p={p}: Square={res['is_square']}, D={res['D'] if res['is_square'] else 'N/A'}, q={res['q_candidate']}, q_prime={res['q_is_prime']}, Valid={res['valid_solution']}")
